<?php if($order):?><section class="order-admin"><h2><?=t('Заказ','Order')?> №<?=$order['id']?></h2><p><?=h($order['customer_name'])?> · <?=h($order['phone'])?> · <?=h($order['email'])?></p><p><?=h($order['address'])?></p><p><?=nl2br(h($order['comment']))?></p><div class="table-scroll"><table><thead><tr><th><?=t('Товар','Item')?></th><th><?=t('Количество','Quantity')?></th><th><?=t('Цена','Price')?></th><th><?=t('Сумма','Amount')?></th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=h($item['title'])?></td><td><?=$item['quantity']?></td><td><?=h(money((int)$item['unit_price_minor']))?></td><td><?=h(money((int)$item['unit_price_minor']*(int)$item['quantity']))?></td></tr><?php endforeach;?></tbody></table></div><p><?=t('Доставка','Delivery')?>: <?=h(money((int)$order['delivery_minor']))?> · <b><?=t('Итого','Total')?>: <?=h(money((int)$order['total_minor']))?></b></p><form method="post" action="/admin/orders/<?=$order['id']?>"><?=csrfField()?><label><?=t('Статус','Status')?><select name="status"><?php foreach(['new'=>'Новый / New','confirmed'=>'Подтверждён / Confirmed','completed'=>'Выполнен / Completed','cancelled'=>'Отменён / Cancelled'] as $value=>$label):?><option value="<?=$value?>" <?=$order['status']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button><?=t('Изменить статус','Update status')?></button></form><p><?=t('Email администратору','Administrator notification')?>: <b><?=h($order['mail_status'])?></b></p><?php if($order['last_error']):?><p class="error"><?=h($order['last_error'])?></p><?php endif;?><form method="post" action="/admin/orders/<?=$order['id']?>"><?=csrfField()?><input type="hidden" name="action" value="retry"><button><?=t('Повторить неотправленное письмо','Retry unsent email')?></button></form></section><?php endif;?>
<h2><?=t('Все заказы','All orders')?></h2><div class="table-scroll"><table><thead><tr><th>№</th><th><?=t('Дата','Date')?></th><th><?=t('Заказчик','Customer')?></th><th><?=t('Итого','Total')?></th><th><?=t('Статус','Status')?></th><th>Email</th></tr></thead><tbody><?php foreach($orders as $row):?><tr><td><a href="/admin/orders?id=<?=$row['id']?>"><?=$row['id']?></a></td><td><?=h($row['created_at'])?></td><td><?=h($row['customer_name'])?></td><td><?=h(money((int)$row['total_minor']))?></td><td><?=h($row['status'])?></td><td><?=h($row['mail_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$orders):?><p><?=t('Заказов пока нет.','No orders yet.')?></p><?php endif;?>
